arguments.command:
cat > tests/export_test.sh <<'EOF'
#!/bin/bash
# export: a dry run prints one request line per batch.
fail=0
bash bin/export --rows 10 --dry-run | grep -q '^POST /v2/batch rows=1-10 ' || { echo "export dry-run"; fail=1; }
bash bin/export --bogus >/dev/null 2>&1; [ $? = 2 ] || { echo "export usage"; fail=1; }
# ADR-0012: at most 250 rows per request, remainder in the last one (RLY-748)
out=$(bash bin/export --rows 600 --dry-run)
[ "$(echo "$out" | wc -l)" = 3 ] || { echo "export batch count"; fail=1; }
echo "$out" | sed -n 1p | grep -q 'rows=1-250 ' || { echo "export batch 1"; fail=1; }
echo "$out" | sed -n 3p | grep -q 'rows=501-600 ' || { echo "export last batch"; fail=1; }
# current auth header is X-Relay-Key (CHANGELOG 2.4.0 dropped X-Partner-Token)
echo "$out" | grep -q ' X-Relay-Key$' || { echo "export auth header"; fail=1; }
echo "$out" | grep -q 'X-Partner-Token' && { echo "export old header"; fail=1; }
exit $fail
EOF
bash tests/export_test.sh; echo rc=$?
sed -i 's/^# Batch size.*/# Batch size for the partner export (docs\/adr\/0012-partner-batch-size.md): at most 250 rows per request./; s/^EXPORT_BATCH_ROWS=.*/EXPORT_BATCH_ROWS=250/' lib/export/batch.sh
sed -i 's/^# Partner request helpers.*/# Partner request helpers. Auth header: X-Relay-Key (keyed auth since 2.3.0), value from RELAY_PARTNER_KEY./; s/^EXPORT_AUTH_HEADER=.*/EXPORT_AUTH_HEADER=X-Relay-Key/' lib/export/partner.sh
bash scripts/verify.sh; head -4 lib/export/*.sh

